/**
 * Allowlist SVG sanitiser for diagrams stored inside prescriptions. Diagrams are generated by our
 * own code, but they travel through the client-writable `prescription.doc`, so the print renderer
 * must never trust them: only known drawing elements/attributes survive; everything else is dropped.
 */
const ELEMENTS = new Set(["svg", "g", "path", "circle", "ellipse", "line", "rect", "text", "tspan", "polyline", "polygon", "defs", "pattern"]);
const ATTRS = new Set([
  "xmlns", "viewbox", "width", "height", "x", "y", "x1", "y1", "x2", "y2", "cx", "cy", "r", "rx", "ry", "d", "points",
  "fill", "stroke", "stroke-width", "stroke-dasharray", "transform", "font-size", "font-family", "text-anchor",
  "id", "patternunits", "patterntransform", "opacity", "fill-opacity",
]);

const escAttr = (v: string) => v.replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const escText = (v: string) => v.replace(/&(?!(amp|lt|gt|quot|#\d+);)/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

function safeValue(name: string, value: string): boolean {
  const v = value.toLowerCase().replace(/\s+/g, "");
  if (v.includes("javascript:") || v.includes("expression(") || v.includes("data:")) return false;
  // Only same-document paint references, e.g. url(#hatch).
  if (v.includes("url(") && !/^url\(#[a-z0-9_-]+\)$/.test(v)) return false;
  return name !== "id" || /^[a-z0-9_-]+$/i.test(value);
}

export function sanitizeSvg(input: string): string {
  if (!input || input.length > 200_000) return "";
  const out: string[] = [];
  const stack: string[] = [];
  let skipDepth = 0; // inside a disallowed element: drop everything until it closes
  const re = /<!--[\s\S]*?-->|<\/?([a-zA-Z][\w:-]*)((?:\s+[^\s=>/]+(?:\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+))?)*)\s*(\/?)>|([^<]+)|</g;
  for (const m of input.matchAll(re)) {
    const [whole, rawName, rawAttrs = "", selfClose, text] = m;
    if (whole.startsWith("<!--")) continue;
    if (text !== undefined) {
      if (!skipDepth && stack.length) out.push(escText(text));
      continue;
    }
    if (!rawName) continue; // stray "<"
    const name = rawName.toLowerCase();
    const closing = whole.startsWith("</");
    const allowed = ELEMENTS.has(name);
    if (closing) {
      if (skipDepth) {
        if (!allowed) skipDepth--;
        continue;
      }
      if (allowed && stack[stack.length - 1] === name) {
        stack.pop();
        out.push(`</${name}>`);
      }
      continue;
    }
    if (skipDepth || !allowed) {
      if (!selfClose && !allowed) skipDepth++;
      continue;
    }
    const attrs: string[] = [];
    for (const a of rawAttrs.matchAll(/([^\s=>/]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+)))?/g)) {
      const an = a[1]!.toLowerCase();
      const av = a[2] ?? a[3] ?? a[4] ?? "";
      if (!ATTRS.has(an) || an.startsWith("on") || !safeValue(an, av)) continue;
      attrs.push(` ${an === "viewbox" ? "viewBox" : an === "patternunits" ? "patternUnits" : an === "patterntransform" ? "patternTransform" : an}="${escAttr(av)}"`);
    }
    if (selfClose) out.push(`<${name}${attrs.join("")}/>`);
    else {
      out.push(`<${name}${attrs.join("")}>`);
      stack.push(name);
    }
  }
  while (stack.length) out.push(`</${stack.pop()}>`);
  return out.join("");
}

/** Signature must be an inline raster image; anything else is dropped. */
export function safeImageDataUrl(url: string | undefined): string | undefined {
  return url && /^data:image\/(png|jpeg|jpg|webp);base64,[a-z0-9+/=\s]+$/i.test(url) ? url : undefined;
}
